mkitem!{mkstruct!{# [doc = " A slot for passing one message from a sender to a receiver."] struct Packet < T > { # [doc = " Equals `true` if the packet is allocated on the stack."] on_stack : bool , # [doc = " Equals `true` once the packet is ready for reading or writing."] ready : Atomic < bool > , # [doc = " The message."] msg : UnsafeCell < Option < T > > , }}}
mkitem!{mkimpl!{impl < T > Packet < T > { # [doc = " Creates an empty packet on the stack."] fn empty_on_stack () -> Packet < T > { Packet { on_stack : true , ready : AtomicBool :: new (false) , msg : UnsafeCell :: new (None) } } # [doc = " Creates a packet on the stack, containing a message."] fn message_on_stack (msg : T) -> Packet < T > { Packet { on_stack : true , ready : AtomicBool :: new (false) , msg : UnsafeCell :: new (Some (msg)) } } # [doc = " Waits until the packet becomes ready for reading or writing."] fn wait_ready (& self) { let backoff = Backoff :: new () ; while ! self . ready . load (Ordering :: Acquire) { backoff . spin_heavy () ; } } }}}
mkitem!{mkstruct!{# [doc = " Inner representation of a zero-capacity channel."] struct Inner { # [doc = " Senders waiting to pair up with a receive operation."] senders : Waker , # [doc = " Receivers waiting to pair up with a send operation."] receivers : Waker , # [doc = " Equals `true` when the channel is disconnected."] is_disconnected : bool , }}}
mkitem!{mkstruct!{# [doc = " Zero-capacity channel."] pub (crate) struct Channel < T > { # [doc = " Inner representation of the channel."] inner : Mutex < Inner > , # [doc = " Indicates that dropping a `Channel<T>` may drop values of type `T`."] _marker : PhantomData < T > , }}}
mkitem!{mkimpl!{impl < T > Channel < T > { # [doc = " Constructs a new zero-capacity channel."] pub (crate) fn new () -> Self { Channel { inner : Mutex :: new (Inner { senders : Waker :: new () , receivers : Waker :: new () , is_disconnected : false , }) , _marker : PhantomData , } } # [doc = " Writes a message into the packet."] pub (crate) unsafe fn write (& self , token : & mut Token , msg : T) -> Result < () , T > { if token . zero . 0 . is_null () { return Err (msg) ; } unsafe { let packet = & * (token . zero . 0 as * const Packet < T >) ; packet . msg . get () . write (Some (msg)) ; packet . ready . store (true , Ordering :: Release) ; } Ok (()) } # [doc = " Reads a message from the packet."] pub (crate) unsafe fn read (& self , token : & mut Token) -> Result < T , () > { if token . zero . 0 . is_null () { return Err (()) ; } let packet = unsafe { & * (token . zero . 0 as * const Packet < T >) } ; if packet . on_stack { let msg = unsafe { packet . msg . get () . replace (None) } . unwrap () ; packet . ready . store (true , Ordering :: Release) ; Ok (msg) } else { packet . wait_ready () ; unsafe { let msg = packet . msg . get () . replace (None) . unwrap () ; drop (Box :: from_raw (token . zero . 0 as * mut Packet < T >)) ; Ok (msg) } } } # [doc = " Attempts to send a message into the channel."] pub (crate) fn try_send (& self , msg : T) -> Result < () , TrySendError < T > > { let token = & mut Token :: default () ; let mut inner = self . inner . lock () . unwrap () ; if let Some (operation) = inner . receivers . try_select () { token . zero . 0 = operation . packet ; drop (inner) ; unsafe { self . write (token , msg) . ok () . unwrap () ; } Ok (()) } else if inner . is_disconnected { Err (TrySendError :: Disconnected (msg)) } else { Err (TrySendError :: Full (msg)) } } # [doc = " Sends a message into the channel."] pub (crate) fn send (& self , msg : T , deadline : Option < Instant > ,) -> Result < () , SendTimeoutError < T > > { let token = & mut Token :: default () ; let mut inner = self . inner . lock () . unwrap () ; if let Some (operation) = inner . receivers . try_select () { token . zero . 0 = operation . packet ; drop (inner) ; unsafe { self . write (token , msg) . ok () . unwrap () ; } return Ok (()) ; } if inner . is_disconnected { return Err (SendTimeoutError :: Disconnected (msg)) ; } Context :: with (| cx | { let oper = Operation :: hook (token) ; let mut packet = Packet :: < T > :: message_on_stack (msg) ; inner . senders . register_with_packet (oper , (& raw mut packet) as * mut () , cx) ; inner . receivers . notify () ; drop (inner) ; let sel = unsafe { cx . wait_until (deadline) } ; match sel { Selected :: Waiting => unreachable ! () , Selected :: Aborted => { self . inner . lock () . unwrap () . senders . unregister (oper) . unwrap () ; let msg = unsafe { packet . msg . get () . replace (None) . unwrap () } ; Err (SendTimeoutError :: Timeout (msg)) } Selected :: Disconnected => { self . inner . lock () . unwrap () . senders . unregister (oper) . unwrap () ; let msg = unsafe { packet . msg . get () . replace (None) . unwrap () } ; Err (SendTimeoutError :: Disconnected (msg)) } Selected :: Operation (_) => { packet . wait_ready () ; Ok (()) } } }) } # [doc = " Attempts to receive a message without blocking."] pub (crate) fn try_recv (& self) -> Result < T , TryRecvError > { let token = & mut Token :: default () ; let mut inner = self . inner . lock () . unwrap () ; if let Some (operation) = inner . senders . try_select () { token . zero . 0 = operation . packet ; drop (inner) ; unsafe { self . read (token) . map_err (| _ | TryRecvError :: Disconnected) } } else if inner . is_disconnected { Err (TryRecvError :: Disconnected) } else { Err (TryRecvError :: Empty) } } # [doc = " Receives a message from the channel."] pub (crate) fn recv (& self , deadline : Option < Instant >) -> Result < T , RecvTimeoutError > { let token = & mut Token :: default () ; let mut inner = self . inner . lock () . unwrap () ; if let Some (operation) = inner . senders . try_select () { token . zero . 0 = operation . packet ; drop (inner) ; unsafe { return self . read (token) . map_err (| _ | RecvTimeoutError :: Disconnected) ; } } if inner . is_disconnected { return Err (RecvTimeoutError :: Disconnected) ; } Context :: with (| cx | { let oper = Operation :: hook (token) ; let mut packet = Packet :: < T > :: empty_on_stack () ; inner . receivers . register_with_packet (oper , (& raw mut packet) as * mut () , cx) ; inner . senders . notify () ; drop (inner) ; let sel = unsafe { cx . wait_until (deadline) } ; match sel { Selected :: Waiting => unreachable ! () , Selected :: Aborted => { self . inner . lock () . unwrap () . receivers . unregister (oper) . unwrap () ; Err (RecvTimeoutError :: Timeout) } Selected :: Disconnected => { self . inner . lock () . unwrap () . receivers . unregister (oper) . unwrap () ; Err (RecvTimeoutError :: Disconnected) } Selected :: Operation (_) => { packet . wait_ready () ; unsafe { Ok (packet . msg . get () . replace (None) . unwrap ()) } } } }) } # [doc = " Disconnects the channel and wakes up all blocked senders and receivers."] # [doc = ""] # [doc = " Returns `true` if this call disconnected the channel."] pub (crate) fn disconnect (& self) -> bool { let mut inner = self . inner . lock () . unwrap () ; if ! inner . is_disconnected { inner . is_disconnected = true ; inner . senders . disconnect () ; inner . receivers . disconnect () ; true } else { false } } # [doc = " Returns the current number of messages inside the channel."] pub (crate) fn len (& self) -> usize { 0 } # [doc = " Returns the capacity of the channel."] # [allow (clippy :: unnecessary_wraps)] pub (crate) fn capacity (& self) -> Option < usize > { Some (0) } # [doc = " Returns `true` if the channel is empty."] pub (crate) fn is_empty (& self) -> bool { true } # [doc = " Returns `true` if the channel is full."] pub (crate) fn is_full (& self) -> bool { true } }}}